"""Build P2-A2 candidate records from manually visual-verified textbook pages."""
from __future__ import annotations
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'datasets'/'knowledge_qa_candidates.jsonl'
REQUIRED={'question_id','question','question_type','reference_answer','explanation','knowledge_category','process_stage','source_document_id','source_title','source_page','evidence_location','evidence_excerpt','applicable_conditions','required_knowledge_points','difficulty','uncertainty','evidence_verification_status','expert_review_status'}
SOURCES={
 'MOD03':('现代铝电解（本地扫描件，2008 版文件名；版本待人工书目信息核验）','现代铝电解/03 氧化铝在电解质中的溶解及其行为.pdf','PDF p.1；印刷页32'),
 'MOD06':('现代铝电解（同上）','现代铝电解/06 阳极效应.pdf','PDF p.1；印刷页56'),
 'MOD11':('现代铝电解（同上）','现代铝电解/11 现代预焙铝电解槽的基本结构.pdf','PDF p.1；印刷页105'),
 'MOD14':('现代铝电解（同上）','现代铝电解/14 铝电解生产中的参数测量.pdf','PDF p.1；印刷页158'),
 'MOD21':('现代铝电解（同上）','现代铝电解/21 铝电解计算机控制系统的基本结构与功能.pdf','PDF p.1；印刷页357'),
 'MOD22':('现代铝电解（同上）','现代铝电解/22 槽电阻的常规解析（含异常状态分析）.pdf','PDF p.1；印刷页368'),
 'MOD24':('现代铝电解（同上）','现代铝电解/24 氧化铝浓度控制（下料控制）.pdf','PDF p.1；印刷页387'),
 'TECH05':('铝电解生产技术（本地扫描件；版本待核验）','铝电解生产技术/05 铝电解槽的常规操作和测量.pdf','PDF p.1；章节首页'),
 'QA11':('铝电解技术问答（本地扫描件；版本待核验）','铝电解技术问答/11 铝电解生产中的常规测量.pdf','PDF p.1；印刷页193'),
}
def q(i,question,typ,answer,explain,cat,stage,src,excerpt,conditions,points,difficulty,uncertainty='低（页级证据已视觉核验；尚待领域专家审阅）'):
 title,path,page=SOURCES[src]
 return {'question_id':f'K{ i:03d}','question':question,'question_type':typ,'reference_answer':answer,'explanation':explain,'knowledge_category':cat,'process_stage':stage,'source_document_id':src,'source_title':title,'source_page':page,'evidence_location':path,'evidence_excerpt':excerpt,'applicable_conditions':conditions,'required_knowledge_points':points,'difficulty':difficulty,'uncertainty':uncertainty,'evidence_verification_status':'Evidence-Verified','expert_review_status':'Pending external domain-expert review'}
def main():
 records=[
 q(1,'教材将加入电解质后的氧化铝列为哪三种主要去向？','K1', '溶解；结成面壳/炉帮；沉落槽底形成沉淀。','答案直接来自该页的三项枚举，不把它映射为任何日报字段。','氧化铝行为','正常生产', 'MOD03','“三个去向”后的三项列举','该页讨论向电解质加入冷氧化铝的情形',['氧化铝加入后的去向'], '单证据理解'),
 q(2,'依据教材，氧化铝能否顺利溶解与哪些类别因素密切相关？','K2','氧化铝的品种和性质、电解质的性质及状况、加料方式。','回答为教材列出的三类影响因素；未引入具体阈值。','氧化铝行为','正常生产','MOD03','“品种和性质…电解质…加料方式”','仅限该页对氧化铝溶解的概述',['氧化铝溶解','影响因素分类'],'单证据理解'),
 q(3,'现代预焙铝电解槽通常由哪四个大部分构成？','K1','阴极结构、上部结构、母线结构和电气绝缘。','该页对工业铝电解槽构成作四部分概括。','槽体结构','设备结构','MOD11','“阴极结构、上部结构、母线结构和电气绝缘”','教材以大型预焙槽为例；不同槽工艺制度下分结构可有差异',['预焙槽结构','适用范围'],'单证据理解'),
 q(4,'为什么不能把一张预焙槽结构图无条件推广到所有工业铝电解槽？','K5','因为教材明确指出不同槽工艺制度下各部分结构存在较大差异；图示仅为一种 200kA 中心点式下料预焙槽。','需要同时使用“结构随工艺制度差异”与图注的具体示例，故不宜泛化。','槽体结构','设备结构','MOD11','“各部分结构也有较大差异”','仅限教材图示和本章的预焙槽例；不用于识别数据中槽型',['结构差异','图示适用条件'],'条件约束'),
 q(5,'教材所述阳极效应在本章讨论的对象是什么？','K1','熔盐电解中采用炭阳极时发生的一种特殊现象。','答案限定在教材开篇界定的对象，避免泛化到所有电解体系。','阳极效应','异常运行','MOD06','“熔盐电解中采用炭阳极”','本章明确只讨论冰晶石-氧化铝体系中炭阳极相关情形',['阳极效应定义','体系边界'],'单证据理解'),
 q(6,'仅凭“电压升高”能否把某条运行记录判定为阳极效应？','K6','不能。教材把电压上升列为现象之一，并给出体系和电极条件；日报字段又缺少状态码、单位和采样/聚合定义，因此该判定需要直接现场证据。','教材知识与 P2 字段边界共同支持“不可据此作事件 gold”的拒答。','阳极效应与证据边界','异常运行','MOD06','“阳极效应发生时电压上升”','教材现象描述不等于厂方日报事件标签；需要状态机/代码表和采集规则',['阳极效应现象','字段映射边界'],'证据不足','高（拒答结论依赖尚缺失的现场字段证据）'),
 q(7,'在教材给定的槽电阻采样公式中，原始槽电阻 R0(n) 如何由 U(n)、I(n) 与 B 表示？','K3','R0(n) = [U(n) − B] / I(n)。','该式是该页给出的特定采样计算式；符号含义同页定义。','槽电阻','参数关系','MOD22','“R0(n)=(U(n)-B)/I(n)”','适用于教材该节定义的表观槽电阻采样，不可套用到日报“平均/工作电压”列',['表观槽电阻','符号关系'],'单证据理解'),
 q(8,'为什么教材建议以（表观）槽电阻而非直接槽电压作为槽况解析依据？','K2','因为槽电压会随系列电流变化，而理论上槽电阻不应随系列电流变化；电阻采样旨在削弱该干扰。','答案只复述该页的论证方向，不延伸为现场诊断结论。','槽电阻','参数关系','MOD22','“槽电压跟随系列电流变化”','限教材讨论的采样与解析框架，且需满足其符号和采样条件',['槽电压','系列电流','表观槽电阻'],'单证据理解'),
 q(9,'教材对 B 的处理为什么限制了公式结果的解释？','K5','B 是设定常数并非真实反电动势；只有运行条件使真实反电动势等于设定值时，表观槽电阻才是真实槽电阻。','需结合 B 的定义与教材给出的等值条件，不能把公式输出直接称真实电阻。','槽电阻','参数关系','MOD22','“B——表观反电动势（设定常数）”','限教材所述模型和等值条件',['设定常数 B','表观与真实量差异'],'条件约束'),
 q(10,'教材所述早期单机群控系统可采集/监控的两个主要信号类别是什么？','K1','系列电流和各槽槽电压。','该页描述单机群控系统的信号采样与监控；不等同于当前日报字段的来源。','控制与信息系统','正常生产','MOD21','“系列电流、各槽的槽电压”','描述教材中的历史控制系统阶段；不能推断本数据集控制系统配置',['控制系统','信号采样'],'单证据理解'),
 q(11,'教材列举的正常生产常规操作中，哪些项目被描述为基本仍依赖人工或人工配合天车完成？','K2','换阳极、出铝、抬母线、铝水平和电解质水平测量。','该页区分了计算机可完成/实现的作业与基本仍依赖人工的作业。','常规操作','正常生产','TECH05','“基本上都还依赖人工”','限大型预焙槽语境及教材所述技术阶段',['常规操作','自动化与人工边界'],'单证据理解'),
 q(12,'常规测量中，“一点测定”和“多点测定”分别服务于什么目的？','K5','一点测定用于每天粗略了解技术条件变化；多点测定用于技术条件管理、决定出铝量或临时全面分析等用途。','答案保留教材对用途的区分，不把它替代为日报统计窗定义。','参数测量','正常生产','MOD14','“一点测定…粗略了解技术条件变化”','本页讨论人工常规测定；不同槽容量/目的下点数可不同',['一点与多点测定','测量目的'],'条件约束'),
 q(13,'为什么不能从“日报”二字推出某一列一定是全天连续测量的日平均？','K6','不能。教材既说明常规测量可是一点或多点且目的不同，也说明需计算机录入；日报文件本身未给出该列的采样频率、聚合公式或生成时点。','这是以教材测量多样性和 P2 数据契约缺口共同支持的合理拒答。','测量与证据边界','正常生产','MOD14','“一点测定与多点测定之分”','结论仅针对当前缺少直接数据字典的日报；需要厂方定义后才能升级',['测量方式差异','字段统计窗证据'],'证据不足','高（需要现场数据字典确认）'),
 q(14,'教材在常规测量项目中列出哪些与电解槽运行有关的测量类别？','K1','包括阳极电流分布、铝液和电解质高度、温度、槽帮形状、炉底压降/温度、极距、热场/磁场，以及电解质密度/电导率/酸碱度等分析测量。','答案为该页列举的类别摘要；相同类别按语义合并。','参数测量','正常生产','QA11','“常规测量项目主要有”','教材列举，不表示这些量均存在于当前数据集',['常规测量项目','字段边界'],'单证据理解'),
 q(15,'教材图示的定时下料控制中，效应等待开始后发生停电或人工翻片时，控制系统如何处理等待极限时间？','K4','教材称控制系统会相应延长等待的极限时间；这一回答仅描述图示模式，不能映射到日报的“设定NB”或“效应状态”。','需要读取图中/文中的等待起点与异常分支，并保持字段映射拒答。','氧化铝浓度控制','正常生产','MOD24','“等待的极限时间作相应延长”','仅限传统定时下料典型模式；不作为本厂控制逻辑事实',['定时下料','效应等待','异常分支'],'多证据推理','中（需专家确认术语译解和控制系统版本）')]
 assert len(records)==15
 for r in records:
  assert REQUIRED==set(r), (r['question_id'], REQUIRED-set(r),set(r)-REQUIRED)
  assert r['source_document_id'] in SOURCES
  assert r['evidence_verification_status']=='Evidence-Verified'
  assert r['expert_review_status']!='Expert-Approved'
 assert len({r['question_id'] for r in records})==len(records)
 OUT.parent.mkdir(parents=True,exist_ok=True)
 OUT.write_text(''.join(json.dumps(r,ensure_ascii=False,separators=(',',':'))+'\n' for r in records),encoding='utf-8')
 print(json.dumps({'records':len(records),'status_counts':{'Evidence-Verified':len(records),'Expert-Approved':0}},ensure_ascii=False))
if __name__=='__main__': main()
